public String gridChallenge(List<String> grid) {
    int n = grid.size();
    char[][] rows = new char[n][];
    for (int i = 0; i < n; i++) {
        rows[i] = grid.get(i).toCharArray();
    }
    return search(rows, 0) ? "YES" : "NO";
}

private boolean search(char[][] rows, int r) {
    if (r == rows.length) {
        for (int j = 0; j < rows[0].length; j++) {
            for (int i = 1; i < rows.length; i++) {
                if (rows[i][j] < rows[i - 1][j]) return false;
            }
        }
        return true;
    }
    return permuteRow(rows, r, 0);
}

private boolean permuteRow(char[][] rows, int r, int start) {
    if (start == rows[r].length) return search(rows, r + 1);
    for (int i = start; i < rows[r].length; i++) {
        char t = rows[r][start]; rows[r][start] = rows[r][i]; rows[r][i] = t;
        if (permuteRow(rows, r, start + 1)) return true;
        t = rows[r][start]; rows[r][start] = rows[r][i]; rows[r][i] = t;
    }
    return false;
}

