from itertools import permutations, product

def gridChallenge(grid: list[str]) -> str:
    per_row = [list(set(permutations(row))) for row in grid]
    for combo in product(*per_row):
        ok = True
        for j in range(len(combo[0])):
            for i in range(1, len(combo)):
                if combo[i][j] < combo[i - 1][j]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return "YES"
    return "NO"

