    for (int i = 0; i < n; i++) {
        rows[i] = grid.get(i).toCharArray();
        Arrays.sort(rows[i]);
    }
    int m = rows[0].length;
    for (int j = 0; j < m; j++) {
        for (int i = 1; i < n; i++) {
            if (rows[i][j] < rows[i - 1][j]) {
                return "NO";
            }
        }
    }
    return "YES";
}

